import { ReactElement, useState } from 'react';

import {
  DONUT_LABEL_MIN_SPACE_RATIO,
  DONUT_LABEL_RING_GAPS,
  DONUT_SIZE_TIER_LABELED_CHART_SIZES,
  DONUT_SIZE_TIER_CUTPOINTS,
} from '@spectrum-charts/core-s2/constants';
import { ChartData } from '@spectrum-charts/vega-spec-builder-s2';

import { Chart } from '../../../Chart.js';
import useChartProps from '../../../hooks/useChartProps.js';
import { Donut } from '../../../components/index.js';
import { DonutProps } from '../../../types/index.js';

const THUMB_HEIGHT = 32;
const REACH_RATIO = 1 + DONUT_LABEL_MIN_SPACE_RATIO;

/** Counts how many breakpoints a size has reached, which is its size tier index (XS = 0). */
const countReached = (breakpoints: number[], size: number): number =>
  breakpoints.filter((breakpoint) => size >= breakpoint).length;

/** Mirrors the spec builder: the tier comes from chart size, not the donut's own diameter. */
const getSizeTierIndex = (containerWidth: number): number =>
  countReached(DONUT_SIZE_TIER_LABELED_CHART_SIZES, containerWidth);

export const getEffectiveDiameter = (containerWidth: number): number => {
  const tierIndex = getSizeTierIndex(containerWidth);
  // half the container, minus 2px padding and the label gap, doubled back to a diameter
  const diameter = (2 * (containerWidth / 2 - 2 - DONUT_LABEL_RING_GAPS[tierIndex])) / REACH_RATIO;
  // capped at the next tier's min diameter, same as the spec builder
  return Math.min(diameter, DONUT_SIZE_TIER_CUTPOINTS[tierIndex] ?? Number.POSITIVE_INFINITY);
};

// donut + widest labels, + 2px padding on both sides, + the label gap on both sides
export const getContainerWidthForDiameter = (diameter: number): number =>
  diameter * REACH_RATIO + 4 + 2 * DONUT_LABEL_RING_GAPS[countReached(DONUT_SIZE_TIER_CUTPOINTS, diameter)];

// 50px past the XL breakpoint so the slider can reach XL
const CHART_SIZE = (DONUT_SIZE_TIER_LABELED_CHART_SIZES.at(-1) ?? 0) + 50;
const MAX_WIDTH = CHART_SIZE + 100;

const HANDLE_STYLES = `
  .rsc-dl-size-handle {
    -webkit-appearance: none;
    appearance: none;
    background: transparent;
    border: none;
    outline: none;
    position: absolute;
    top: 0;
    left: 0;
    height: ${CHART_SIZE}px;
    pointer-events: none;
    z-index: 20;
  }
  .rsc-dl-size-handle::-webkit-slider-runnable-track {
    background: transparent;
    height: ${CHART_SIZE}px;
  }
  .rsc-dl-size-handle::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 8px;
    height: ${THUMB_HEIGHT}px;
    border-radius: 4px;
    background: #999;
    cursor: ew-resize;
    pointer-events: all;
    margin-top: ${(CHART_SIZE - THUMB_HEIGHT) / 2}px;
  }
  .rsc-dl-size-handle::-moz-range-track { background: transparent; }
  .rsc-dl-size-handle::-moz-range-thumb {
    width: 8px;
    height: ${THUMB_HEIGHT}px;
    border-radius: 4px;
    background: #999;
    border: none;
    cursor: ew-resize;
  }
`;

const TIER_LABELS = ['XS', 'S', 'M', 'L', 'XL'];
const THRESHOLDS = DONUT_SIZE_TIER_CUTPOINTS.map((cutpoint, i) => ({
  px: DONUT_SIZE_TIER_LABELED_CHART_SIZES[i],
  label: TIER_LABELS[i + 1],
  diameter: cutpoint,
}));

const getSizeTier = (containerWidth: number): string => TIER_LABELS[getSizeTierIndex(containerWidth)];

export const ResponsiveDonut = ({
  data,
  donutProps,
  children,
  initialWidth = 300,
}: {
  data: ChartData[];
  donutProps?: Partial<DonutProps>;
  children: DonutProps['children'];
  initialWidth?: number;
}): ReactElement => {
  const [width, setWidth] = useState(initialWidth);
  const chartProps = useChartProps({ data });
  const outerDiameter = getEffectiveDiameter(width);
  const currentSize = getSizeTier(width);

  return (
    <div style={{ padding: '16px 0' }}>
      <style>{HANDLE_STYLES}</style>
      <div style={{ marginBottom: 8, fontSize: 13, color: '#666' }}>
        Container Width: <strong>{Math.round(width)}px</strong> — Outer Diameter:{' '}
        <strong>{Math.round(outerDiameter)}px</strong> — Size tier: <strong>{currentSize}</strong>
      </div>
      <div style={{ position: 'relative', minWidth: MAX_WIDTH }}>
        {THRESHOLDS.map(({ px, label, diameter }) => (
          <div
            key={label}
            style={{
              position: 'absolute',
              left: px,
              top: 0,
              bottom: 0,
              width: 1,
              background: 'rgba(220, 60, 60, 0.6)',
              zIndex: 10,
              pointerEvents: 'none',
            }}
          >
            <span
              style={{
                position: 'absolute',
                top: 2,
                left: 3,
                fontSize: 10,
                color: 'rgba(220, 60, 60, 0.9)',
                whiteSpace: 'nowrap',
                lineHeight: 1,
              }}
            >
              {label} ({diameter}px)
            </span>
          </div>
        ))}
        <div style={{ position: 'relative', display: 'inline-block' }}>
          <Chart {...chartProps} width={width} height={CHART_SIZE}>
            <Donut metric="count" color="browser" {...donutProps}>
              {children}
            </Donut>
          </Chart>
          <input
            type="range"
            className="rsc-dl-size-handle"
            aria-label="Chart width"
            min={0}
            max={MAX_WIDTH}
            value={Math.round(width)}
            onChange={(event) => setWidth(Math.max(50, Number(event.target.value)))}
            style={{ width: MAX_WIDTH }}
          />
        </div>
      </div>
    </div>
  );
};
